<script setup lang="ts">
import {ref,onMounted} from 'vue';
import {api,type Page} from './api';
import Dialog from './Dialog.vue';
const props=defineProps<{run:(work:()=>Promise<void>)=>Promise<void>;busy:boolean;requestError?:string}>();
type Device={id:string;user_agent:string;first_ip:string|null;last_ip:string|null;first_seen:string;last_seen:string;login_count:string;status:string;can_review:boolean;current:boolean};
const data=ref<(Page<Device>&{devices:string;pending:string;approved:string;rejected:string;enabled:boolean;can_review:boolean})|null>(null),error=ref('');
const search=ref(''),status=ref('ALL'),from=ref(''),to=ref(''),page=ref(1),pageSize=ref(20),confirmation=ref<Record<string,string|boolean>|null>(null);
const date=(v:string)=>new Date(v).toLocaleString();
async function load(){data.value=await api(`operator/devices?${new URLSearchParams({search:search.value,status:status.value,page:String(page.value),pageSize:String(pageSize.value),...(from.value?{from:from.value}:{}),...(to.value?{to:to.value}:{})})}`);}
function filter(){page.value=1;void props.run(load);}
function turn(delta:number){page.value+=delta;void props.run(load);}
function reset(){search.value='';status.value='ALL';from.value='';to.value='';filter();}
async function confirm(){await props.run(async()=>{await api('operator/devices',confirmation.value);confirmation.value=null;await load();});}
onMounted(()=>{void load().catch(e=>error.value=(e as Error).message);});
</script>
<template><section class="device-page"><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="data"><div class="device-stats"><article v-for="item in [['Total Devices',data.devices],['Pending',data.pending],['Approved',data.approved],['Rejected',data.rejected]]" :key="item[0]"><strong>{{item[1]}}</strong><span>{{item[0]}}</span></article></div><form class="filters" @submit.prevent="filter"><div class="filter-row"><label>Device Code<input v-model="search" placeholder="Device ID"></label><label>Review Status<select v-model="status"><option value="ALL">All</option><option value="PENDING">Pending</option><option value="APPROVED">Approved</option><option value="REJECTED">Rejected</option></select></label><label>Login Time<input v-model="from" type="date"></label><span>To</span><input v-model="to" type="date" aria-label="Login end date"><button class="primary" :disabled="busy">Search</button><button type="button" :disabled="busy" @click="reset">Reset</button></div></form><div class="filter-row review-switch"><b>Enable Review</b><button role="switch" aria-label="Enable Review" :aria-checked="data.enabled" :disabled="busy||(!data.can_review&&data.enabled)" class="switch" :class="{on:data.enabled}" @click="confirmation={action:'SET_REVIEW',enabled:!data.enabled}"><span/></button></div><p class="note">Enabling review approves this device. Other devices must then be approved before signing in.</p><div class="table-scroll"><table><thead><tr><th>Device ID</th><th>Device Info</th><th>Terminal</th><th>Access</th><th>Time</th><th>Status</th><th>Review Device</th><th>Operation</th></tr></thead><tbody><tr v-for="device in data.items" :key="device.id"><td class="mono">{{device.id}}</td><td><span v-if="device.current" class="badge">Current</span><span v-else>Login device</span></td><td class="device-agent">{{device.user_agent}}</td><td>First: {{device.first_ip||'—'}}<br>Latest: {{device.last_ip||'—'}}<br>{{device.login_count}} times</td><td>{{date(device.first_seen)}}<br>{{date(device.last_seen)}}</td><td>{{device.status}}</td><td>{{device.can_review?'Yes':'No'}}</td><td><div v-if="data.can_review" class="row-actions"><button v-if="device.status!=='APPROVED'" class="link" :disabled="busy" @click="confirmation={action:'APPROVE',id:device.id}">Approve</button><button v-if="!device.current&&device.status!=='REJECTED'" class="link" :disabled="busy" @click="confirmation={action:'REJECT',id:device.id}">Reject</button><button v-if="!device.current&&device.status==='APPROVED'" class="link" :disabled="busy" @click="confirmation={action:device.can_review?'REVOKE_REVIEW':'ALLOW_REVIEW',id:device.id}">{{device.can_review?'Remove review':'Allow review'}}</button></div></td></tr><tr v-if="!data.items.length"><td colspan="8" class="empty">No Data</td></tr></tbody></table></div><footer class="pagination"><button :disabled="busy||page===1" @click="turn(-1)">prev</button><button :disabled="busy||page*pageSize>=Number(data.total)" @click="turn(1)">next</button><select v-model="pageSize" aria-label="Device rows per page" @change="filter"><option :value="20">20/page</option><option :value="50">50/page</option></select><span>{{data.total}} total</span></footer></template></section><Dialog v-if="confirmation" title="Login Device" :busy="busy" @close="confirmation=null"><p>{{confirmation.action==='SET_REVIEW'?(confirmation.enabled?'Enable device review? Unapproved sessions will be signed out.':'Disable device review? Password sign-in will be available on other devices.'):confirmation.action==='REJECT'?'Reject this device and sign out its sessions?':confirmation.action==='APPROVE'?'Approve this device for sign-in?':confirmation.action==='ALLOW_REVIEW'?'Allow this device to review other devices?':'Remove review permission from this device?'}}</p><p v-if="requestError" class="error" role="alert">{{requestError}}</p><footer><button :disabled="busy" @click="confirmation=null">Cancel</button><button class="primary" :disabled="busy" @click="confirm">Confirm</button></footer></Dialog></template>
